'use strict';
const $=id=>document.getElementById(id);
let direction='new', timer, fileBase='harf';
const sample="O‘zbekiston — go‘zal o‘lka. Shahar ko‘chalari, tog‘lar va chiroyli bog‘lar.\n\nMa’rifat bilan kelajak sari!\nhttps://example.com/shahar — havolalar o‘zgarmaydi.";
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');$('status').textContent=message;clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
function update(){const result=Harf.convert($('source').value,direction);$('result').value=result.text;$('input-count').textContent=Array.from($('source').value).length.toLocaleString('uz-UZ')+' belgi';$('changes').textContent=result.changes.toLocaleString('uz-UZ')+' ta o‘zgarish';$('copy').disabled=$('save').disabled=!result.text;}
function select(next){direction=next;const forward=next==='new';$('forward').classList.toggle('selected',forward);$('reverse').classList.toggle('selected',!forward);$('forward').setAttribute('aria-pressed',String(forward));$('reverse').setAttribute('aria-pressed',String(!forward));$('source-label').textContent=forward?'Eski alifbodagi matn':'Yangi alifbodagi matn';$('result-label').textContent=forward?'Yangi alifbodagi matn':'Eski alifbodagi matn';$('source').placeholder=forward?'O‘zbekiston — go‘zal o‘lka. Matningizni kiriting…':'Özbekiston — gözal ölka. Matningizni kiriting…';$('result').placeholder=forward?'Özbekiston — gözal ölka. Natija shu yerda paydo bo‘ladi…':'O‘zbekiston — go‘zal o‘lka. Natija shu yerda paydo bo‘ladi…';update();}
$('source').addEventListener('input',update);
$('forward').onclick=()=>select('new');$('reverse').onclick=()=>select('old');
$('example').onclick=()=>{$('source').value=direction==='new'?sample:Harf.convert(sample).text;update();toast('Namuna qo‘yildi');};
$('clear').onclick=()=>{$('source').value='';fileBase='harf';update();$('source').focus();};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('result').value);toast('Matn nusxalandi');}catch{ $('result').focus();$('result').select();toast('Nusxalash uchun Ctrl+C bosing');}};
$('save').onclick=()=>{const blob=new Blob(['\uFEFF'+$('result').value],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=fileBase+(direction==='new'?'-yangi':'-eski')+'.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Natija yuklab olindi');};
$('file').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(!/\.(txt|md|csv|srt)$/i.test(file.name))throw new Error('Faqat .txt, .md, .csv va .srt fayllarini oching.');if(file.size>10*1024*1024)throw new Error('Fayl hajmi 10 MB dan oshmasligi kerak.');const buffer=await file.arrayBuffer();let decoded;try{decoded=new TextDecoder('utf-8',{fatal:true}).decode(buffer);}catch{throw new Error('Fayl UTF-8 kodlashda bo‘lishi kerak.');}if(decoded.includes('\0'))throw new Error('Bu matn fayliga o‘xshamaydi.');$('source').value=decoded;fileBase=file.name.replace(/\.[^.]+$/,'');update();toast('Fayl ochildi va o‘girildi');}catch(error){toast(error.message);}finally{event.target.value='';}};
update();
